class _PubIgnoreRule {
  _PubIgnoreRule(this.line)
    : negated = line.startsWith('!'),
      dirOnly = line.endsWith('/') {
    var body = line;
    if (negated) body = body.substring(1);
    if (dirOnly) body = body.substring(0, body.length - 1);
    var anchored = body.startsWith('/');
